def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = sum(1 for a in opp if a == 'C')
    opp_rate = opp_c / n

    if opp_rate < 0.2:
        return 'D'

    recent_len = min(10, n)
    recent_opp = opp[-recent_len:]
    recent_opp_c = sum(1 for a in recent_opp if a == 'C')
    recent_opp_rate = recent_opp_c / recent_len

    if recent_len >= 5 and recent_opp_rate < 0.3:
        return 'D'

    recent_my = my[-recent_len:]
    recent_my_d = sum(1 for a in recent_my if a == 'D')
    recent_my_def_rate = recent_my_d / recent_len

    forgive = 0
    punish = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'C':
                forgive += 1
            else:
                punish += 1
    total_responses = forgive + punish
    forgiveness = forgive / total_responses if total_responses > 0 else 0.5

    last_opp = opp[-1]
    last_my = my[-1]

    if last_opp == 'D':
        if last_my == 'D':
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if my[i] == 'D' and opp[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 2 and rng.random() < 0.3:
                return 'C'
            return 'D'
        else:
            if recent_opp_rate > 0.6:
                if rng.random() < 0.7:
                    return 'C'
                return 'D'
            else:
                if rng.random() < 0.15:
                    return 'C'
                return 'D'

    if last_my == 'D':
        return 'C'

    if recent_opp_rate > 0.7:
        if total_responses > 0 and punish == 0:
            prob = 0.8
        else:
            prob = forgiveness * 0.6

        if recent_my_def_rate > 0.3:
            prob *= 0.5
        if recent_my_def_rate > 0.5:
            prob = 0.0

        if n >= 2 and ('D' in my[-2:]):
            prob *= 0.3

        if rng.random() < prob:
            return 'D'

    return 'C'
